// Generated by scripts/generate-bcrypt-kernels.swift; don't edit. bcrypt's key-only expansion written out per lane
// count and kernel family: every lane's halves in locals, all 16 rounds of every lane in order.
import Synchronization

#if arch(x86_64)
/// The shrx kernels' shift counts, so the shifts take their count from a register. Not `private`: a private
/// global is internal to the object file, where the optimizer sees every access and folds the loads back to
/// constants (the kernels then compile to the constant family's, which is only slower where that's slower);
/// a module-internal one is an external symbol, whose value it can't assume.
let bcryptShiftBy24 = Atomic<UInt32>(24)
let bcryptShiftBy16 = Atomic<UInt32>(16)
#endif

/// ExpandKey(state, 0, key) in every lane (P already mixed with the key), by `kernel`'s kernel written out for
/// `n` lanes (1 to 6).
@inline(__always) func expandKeyOnly<let n: Int>(_ states: inout InlineArray<n, BlowfishState>, _ kernel: BcryptKernel) {
    switch kernel {
    case .constant:
        switch n {
        case 1: expandKeyOnly1(&states)
        case 2: expandKeyOnly2(&states)
        case 3: expandKeyOnly3(&states)
        case 4: expandKeyOnly4(&states)
        case 5: expandKeyOnly5(&states)
        case 6: expandKeyOnly6(&states)
        default: fatalError("no bcrypt kernel for \(n) lanes")
        }
    #if arch(x86_64)
    case .shrx:
        switch n {
        case 1: expandKeyOnlyShrx1(&states)
        case 2: expandKeyOnlyShrx2(&states)
        case 3: expandKeyOnlyShrx3(&states)
        case 4: expandKeyOnlyShrx4(&states)
        case 5: expandKeyOnlyShrx5(&states)
        case 6: expandKeyOnlyShrx6(&states)
        default: fatalError("no bcrypt kernel for \(n) lanes")
        }
    #endif
    }
}

/// F of lane `k`, its S-boxes read in place.
@inline(__always) private func feistel<let m: Int>(_ states: borrowing InlineArray<m, BlowfishState>, _ k: Int,
    _ x: UInt32) -> UInt32 {
    ((states[k].s[Int(x >> 24)] &+ states[k].s[256 + Int(x >> 16 & 0xFF)]) ^ states[k].s[512 + Int(x >> 8 & 0xFF)])
        &+ states[k].s[768 + Int(x & 0xFF)]
}

/// One Blowfish block encryption in each of 1 lane(s): `L ^= P[0]`, sixteen half-rounds `y ^= P[r] ^ F(x)`,
/// then `(L, R) = (R ^ P[17], L)`.
@inline(__always) private func encrypt1<let m: Int>(_ states: borrowing InlineArray<m, BlowfishState>,
    _ l0: inout UInt32, _ r0: inout UInt32) {
    l0 ^= states[0].p[0]
    r0 ^= states[0].p[1]
    r0 ^= feistel(states, 0, l0)
    l0 ^= states[0].p[2]
    l0 ^= feistel(states, 0, r0)
    r0 ^= states[0].p[3]
    r0 ^= feistel(states, 0, l0)
    l0 ^= states[0].p[4]
    l0 ^= feistel(states, 0, r0)
    r0 ^= states[0].p[5]
    r0 ^= feistel(states, 0, l0)
    l0 ^= states[0].p[6]
    l0 ^= feistel(states, 0, r0)
    r0 ^= states[0].p[7]
    r0 ^= feistel(states, 0, l0)
    l0 ^= states[0].p[8]
    l0 ^= feistel(states, 0, r0)
    r0 ^= states[0].p[9]
    r0 ^= feistel(states, 0, l0)
    l0 ^= states[0].p[10]
    l0 ^= feistel(states, 0, r0)
    r0 ^= states[0].p[11]
    r0 ^= feistel(states, 0, l0)
    l0 ^= states[0].p[12]
    l0 ^= feistel(states, 0, r0)
    r0 ^= states[0].p[13]
    r0 ^= feistel(states, 0, l0)
    l0 ^= states[0].p[14]
    l0 ^= feistel(states, 0, r0)
    r0 ^= states[0].p[15]
    r0 ^= feistel(states, 0, l0)
    l0 ^= states[0].p[16]
    l0 ^= feistel(states, 0, r0)
    (l0, r0) = (r0 ^ states[0].p[17], l0)
}

/// The key-only expansion of 1 lane(s): 521 encryptions chained from zero, filling P and then the S-boxes.
/// Generic over the array's size (always 1) so the states are reached in place, never copied.
@inline(__always) private func expandKeyOnly1<let m: Int>(_ states: inout InlineArray<m, BlowfishState>) {
    var l0: UInt32 = 0, r0: UInt32 = 0
    for i in 0..<9 {
        encrypt1(states, &l0, &r0)
        states[0].p[2 * i] = l0; states[0].p[2 * i + 1] = r0
    }
    for i in 0..<512 {
        encrypt1(states, &l0, &r0)
        states[0].s[2 * i] = l0; states[0].s[2 * i + 1] = r0
    }
}

