    var l0: UInt32 = 0, r0: UInt32 = 0; var l1: UInt32 = 0, r1: UInt32 = 0; var l2: UInt32 = 0, r2: UInt32 = 0; var l3: UInt32 = 0, r3: UInt32 = 0
