        encrypt4(states, &l0, &r0, &l1, &r1, &l2, &r2, &l3, &r3)
        states[0].p[2 * i] = l0; states[0].p[2 * i + 1] = r0
        states[1].p[2 * i] = l1; states[1].p[2 * i + 1] = r1
        states[2].p[2 * i] = l2; states[2].p[2 * i + 1] = r2
        states[3].p[2 * i] = l3; states[3].p[2 * i + 1] = r3
    }
    for i in 0..<512 {
