        states[1].s[2 * i] = l1; states[1].s[2 * i + 1] = r1
        states[2].s[2 * i] = l2; states[2].s[2 * i + 1] = r2
        states[3].s[2 * i] = l3; states[3].s[2 * i + 1] = r3
        states[4].s[2 * i] = l4; states[4].s[2 * i + 1] = r4
        states[5].s[2 * i] = l5; states[5].s[2 * i + 1] = r5
    }
