/// F of lane `k`, its S-boxes read in place.
@inline(__always) private func feistelShrx<let m: Int>(_ states: borrowing InlineArray<m, BlowfishState>, _ k: Int,
    _ x: UInt32, _ by24: UInt32, _ by16: UInt32) -> UInt32 {
    ((states[k].s[Int(x &>> by24)] &+ states[k].s[256 + Int(x &>> by16 & 0xFF)])
        ^ states[k].s[512 + Int(x >> 8 & 0xFF)]) &+ states[k].s[768 + Int(x & 0xFF)]
}

/// One Blowfish block encryption in each of 1 lane(s): `L ^= P[0]`, sixteen half-rounds `y ^= P[r] ^ F(x)`,
/// then `(L, R) = (R ^ P[17], L)`.
@inline(__always) private func encryptShrx1<let m: Int>(_ states: borrowing InlineArray<m, BlowfishState>,
    _ l0: inout UInt32, _ r0: inout UInt32, _ by24: UInt32, _ by16: UInt32) {
    l0 ^= states[0].p[0]
    r0 ^= states[0].p[1]
    r0 ^= feistelShrx(states, 0, l0, by24, by16)
    l0 ^= states[0].p[2]
    l0 ^= feistelShrx(states, 0, r0, by24, by16)
    r0 ^= states[0].p[3]
    r0 ^= feistelShrx(states, 0, l0, by24, by16)
    l0 ^= states[0].p[4]
    l0 ^= feistelShrx(states, 0, r0, by24, by16)
    r0 ^= states[0].p[5]
    r0 ^= feistelShrx(states, 0, l0, by24, by16)
    l0 ^= states[0].p[6]
    l0 ^= feistelShrx(states, 0, r0, by24, by16)
    r0 ^= states[0].p[7]
    r0 ^= feistelShrx(states, 0, l0, by24, by16)
    l0 ^= states[0].p[8]
    l0 ^= feistelShrx(states, 0, r0, by24, by16)
    r0 ^= states[0].p[9]
    r0 ^= feistelShrx(states, 0, l0, by24, by16)
    l0 ^= states[0].p[10]
    l0 ^= feistelShrx(states, 0, r0, by24, by16)
    r0 ^= states[0].p[11]
    r0 ^= feistelShrx(states, 0, l0, by24, by16)
    l0 ^= states[0].p[12]
    l0 ^= feistelShrx(states, 0, r0, by24, by16)
    r0 ^= states[0].p[13]
    r0 ^= feistelShrx(states, 0, l0, by24, by16)
    l0 ^= states[0].p[14]
    l0 ^= feistelShrx(states, 0, r0, by24, by16)
    r0 ^= states[0].p[15]
    r0 ^= feistelShrx(states, 0, l0, by24, by16)
    l0 ^= states[0].p[16]
    l0 ^= feistelShrx(states, 0, r0, by24, by16)
    (l0, r0) = (r0 ^ states[0].p[17], l0)
}

/// The key-only expansion of 1 lane(s): 521 encryptions chained from zero, filling P and then the S-boxes.
/// Generic over the array's size (always 1) so the states are reached in place, never copied.
@inline(__always) private func expandKeyOnlyShrx1<let m: Int>(_ states: inout InlineArray<m, BlowfishState>) {
    let by24 = bcryptShiftBy24.load(ordering: .relaxed), by16 = bcryptShiftBy16.load(ordering: .relaxed)
