/// The key-only expansion of 6 lane(s): 521 encryptions chained from zero, filling P and then the S-boxes.
/// Generic over the array's size (always 6) so the states are reached in place, never copied.
@inline(__always) private func expandKeyOnlyShrx6<let m: Int>(_ states: inout InlineArray<m, BlowfishState>) {
    let by24 = bcryptShiftBy24.load(ordering: .relaxed), by16 = bcryptShiftBy16.load(ordering: .relaxed)
    var l0: UInt32 = 0, r0: UInt32 = 0; var l1: UInt32 = 0, r1: UInt32 = 0; var l2: UInt32 = 0, r2: UInt32 = 0; var l3: UInt32 = 0, r3: UInt32 = 0; var l4: UInt32 = 0, r4: UInt32 = 0; var l5: UInt32 = 0, r5: UInt32 = 0
    for i in 0..<9 {
        encryptShrx6(states, &l0, &r0, &l1, &r1, &l2, &r2, &l3, &r3, &l4, &r4, &l5, &r5, by24, by16)
        states[0].p[2 * i] = l0; states[0].p[2 * i + 1] = r0
        states[1].p[2 * i] = l1; states[1].p[2 * i + 1] = r1
        states[2].p[2 * i] = l2; states[2].p[2 * i + 1] = r2
        states[3].p[2 * i] = l3; states[3].p[2 * i + 1] = r3
        states[4].p[2 * i] = l4; states[4].p[2 * i + 1] = r4
        states[5].p[2 * i] = l5; states[5].p[2 * i + 1] = r5
    }
    for i in 0..<512 {
        encryptShrx6(states, &l0, &r0, &l1, &r1, &l2, &r2, &l3, &r3, &l4, &r4, &l5, &r5, by24, by16)
        states[0].s[2 * i] = l0; states[0].s[2 * i + 1] = r0
        states[1].s[2 * i] = l1; states[1].s[2 * i + 1] = r1
        states[2].s[2 * i] = l2; states[2].s[2 * i + 1] = r2
        states[3].s[2 * i] = l3; states[3].s[2 * i + 1] = r3
        states[4].s[2 * i] = l4; states[4].s[2 * i + 1] = r4
        states[5].s[2 * i] = l5; states[5].s[2 * i + 1] = r5
    }
}

